urlset:
    
    
        {{ request.scheme }}://{{ request.get_host }}{% url 'core:home' %}
    

    
        {{ request.scheme }}://{{ request.get_host }}{% url 'core:about' %}
    

    
        {{ request.scheme }}://{{ request.get_host }}{% url 'core:contact' %}
    

    
        {{ request.scheme }}://{{ request.get_host }}{% url 'core:privacy' %}
    

    
        {{ request.scheme }}://{{ request.get_host }}{% url 'core:terms' %}
    

    
        {{ request.scheme }}://{{ request.get_host }}{% url 'core:sitemap' %}
    

    
    {% for note in all_notes %}
    
        {{ request.scheme }}://{{ request.get_host }}{{ note.get_absolute_url }}
        {{ note.updated_at|date:"Y-m-d" }}
    
    {% endfor %}

    
    {% for post in all_blogs %}
    
        {{ request.scheme }}://{{ request.get_host }}{{ post.get_absolute_url }}
        {{ post.updated_at|date:"Y-m-d" }}
    
    {% endfor %}

    
    {% for download in all_downloads %}
    
        {{ request.scheme }}://{{ request.get_host }}{{ download.get_absolute_url }}
        {{ download.updated_at|date:"Y-m-d" }}
    
    {% endfor %}

    
    {% for quiz in all_quizzes %}
    
        {{ request.scheme }}://{{ request.get_host }}{{ quiz.get_absolute_url }}
        {{ quiz.updated_at|date:"Y-m-d" }}
    
    {% endfor %}
